anner__category\"><p class=\"brz-cookie-banner__category-label\">Other</p><p class=\"brz-cookie-banner__category-description\">Scripts that do not fit into any of the other categories or are not yet classified.</p><label class=\"brz-cookie-banner__switch\"><input type=\"checkbox\" class=\"brz-cookie-banner__switch-input\" data-brz-cc=\"category-toggle\" data-brz-cc-category=\"other\"><span class=\"brz-cookie-banner__switch-slider\"></span></label></div></div><div class=\"brz-cookie-banner__dialog-footer\"><button type=\"button\" class=\"brz-cookie-banner__btn brz-cookie-banner__btn--dialog-accept\" data-brz-cc=\"accept\"><span data-brz-translate-text=\"1\" class=\"brz-span brz-text__editor\">Accept all</span></button><button type=\"button\" class=\"brz-cookie-banner__btn brz-cookie-banner__btn--save\" data-brz-cc=\"save\"><span data-brz-translate-text=\"1\" class=\"brz-span brz-text__editor\">Save preferences</span></button></div></div></div></div>\n    ","assets":{"freeScripts":{"main":{"name":"main","score":30,"content":{"type":"file","url":"/static/editor/js/preview.min.js","attr":{"class":"brz-script brz-script-preview","defer":"true"}},"pro":false},"version":"no-verify","generic":[{"name":"consentBlocker","score":5,"pro":false,"content":{"type":"inline","content":"(function () {\n  try {\n    var COOKIE_NAME = \"brz-consent\";\n    var VENDOR_MAP = [[/(^|\\.)(google-analytics\\.com|googletagmanager\\.com|analytics\\.google\\.com)$/,\"statistics\"],[/(^|\\.)(clarity\\.ms|hotjar\\.com)$/,\"statistics\"],[/(^|\\.)facebook\\.net$/,\"marketing\"],[/(^|\\.)(doubleclick\\.net|googlesyndication\\.com|googleadservices\\.com)$/,\"marketing\"],[/(^|\\.)(ads-twitter\\.com|ads\\.tiktok\\.com|analytics\\.tiktok\\.com)$/,\"marketing\"],[/(^|\\.)snap\\.licdn\\.com$/,\"marketing\"],[/(^|\\.)pinimg\\.com$/,\"marketing\"],[/(^|\\.)(youtube\\.com|ytimg\\.com)$/,\"marketing\"],[/(^|\\.)(twitter\\.com|twimg\\.com|x\\.com)$/,\"marketing\"],[/(^|\\.)(instagram\\.com|cdninstagram\\.com